async (page) => {
  const paths = [
    "/trading", "/risk", "/strategies", "/strategies/audit-missing",
    "/validation", "/validation/backtests/audit-missing", "/validation/optimizations/audit-missing",
    "/review", "/research", "/research/sources/audit-missing", "/ops"
  ];
  const results = [];
  const consoleEntries = [];
  page.on("console", msg => {
    if (msg.type() === "error" || msg.type() === "warning") consoleEntries.push({ type: msg.type(), text: msg.text() });
  });
  page.on("pageerror", error => consoleEntries.push({ type: "pageerror", text: error.message }));
  for (const path of paths) {
    await page.setViewportSize({ width: 1440, height: 900 });
    await page.goto("http://127.0.0.1:5174" + path, { waitUntil: "networkidle", timeout: 15000 }).catch(() => {});
    await page.waitForTimeout(300);
    const body = await page.locator("body").innerText().catch(() => "");
    const requests = await page.evaluate(() => performance.getEntriesByType("resource").map(x => x.name).filter(x => x.includes("/api/")));
    results.push({
      path,
      title: await page.title(),
      has_navigation: body.includes("交易台") && body.includes("风控"),
      body_excerpt: body.slice(0, 240),
      api_request_count: requests.length
    });
  }
  await page.setViewportSize({ width: 390, height: 844 });
  await page.goto("http://127.0.0.1:5174/trading", { waitUntil: "networkidle", timeout: 15000 }).catch(() => {});
  const overflow = await page.evaluate(() => document.documentElement.scrollWidth > window.innerWidth);
  return { results, consoleEntries, mobile_trading_horizontal_overflow: overflow };
}

