"""Ignored audit harness for exchange client-order-id propagation."""

from __future__ import annotations

import json

from services.execution.gateway import BinanceUsdtPerpetualGateway
from shared.models import ExecutionOrderRequest


class RecordingClient:
    def __init__(self) -> None:
        self.markets: dict[str, object] = {}
        self.calls: list[tuple[object, ...]] = []

    def load_markets(self) -> None:
        self.markets = {"BTC/USDT:USDT": {}}

    @staticmethod
    def market(_symbol: str) -> dict[str, object]:
        return {"limits": {"amount": {"min": 0.001}}}

    @staticmethod
    def amount_to_precision(_symbol: str, quantity: float) -> str:
        return f"{quantity:.3f}"

    def create_order(self, *args: object) -> dict[str, str]:
        self.calls.append(args)
        return {"id": str(len(self.calls)), "status": "open"}


def main() -> None:
    client = RecordingClient()
    gateway = BinanceUsdtPerpetualGateway(client=client, use_testnet=False)
    request = ExecutionOrderRequest(
        strategy_id="audit",
        symbol="BTC/USDT",
        direction="long",
        entry_context={"quantity": 0.5, "reference_price": 100, "requested_notional": 50},
        stoploss_plan={"price": 95},
        takeprofit_plan={"price": 105},
        idempotency_key="audit-stable-idempotency-key",
    )
    first = gateway.submit_order(live_run_id="audit-run", order_request=request)
    second = gateway.submit_order(live_run_id="audit-run", order_request=request)
    params = [call[-1] for call in client.calls]
    client_order_id_keys = {"clientOrderId", "newClientOrderId", "client_order_id"}
    assert len(client.calls) == 2
    assert all(not (set(item) & client_order_id_keys) for item in params if isinstance(item, dict))
    print(
        json.dumps(
            {
                "gateway_submit_calls": len(client.calls),
                "gateway_order_ids": [first["gateway_order_id"], second["gateway_order_id"]],
                "request_idempotency_key": "present",
                "client_order_id_propagated": False,
            },
            sort_keys=True,
        )
    )


if __name__ == "__main__":
    main()

